-- J4c-4b — VERIFICAÇÃO (somente leitura; só nomes e contagens). Esperado: 6 policies; visitante sem nada; quadro sem dado pessoal; 3 funções seguras; dados iguais ao registro.
select 'policies nas 3 tabelas (esperado 6)' as item, (select count(*) from pg_policies where schemaname = 'public' and tablename in ('claim_eventos', 'claim_sets', 'claim_reservas'))::text as valor
union all select 'policies para visitante/PUBLIC (esperado 0)', (select count(*) from pg_policies where schemaname = 'public' and tablename in ('claim_eventos', 'claim_sets', 'claim_reservas') and ('anon' = any(roles) or 'public' = any(roles)))::text
union all select 'RLS ligado nas 3 tabelas (esperado 3)', (select count(*) from pg_class where oid in ('public.claim_eventos'::regclass, 'public.claim_sets'::regclass, 'public.claim_reservas'::regclass) and relrowsecurity)::text
union all select 'visitante com algum privilégio nas 3 tabelas ou no quadro (esperado false)',
       (select coalesce(bool_or(has_table_privilege('anon', x.nome, 'SELECT') or has_table_privilege('anon', x.nome, 'INSERT') or has_table_privilege('anon', x.nome, 'UPDATE') or has_table_privilege('anon', x.nome, 'DELETE') or has_any_column_privilege('anon', x.nome, 'SELECT') or has_any_column_privilege('anon', x.nome, 'UPDATE') or has_any_column_privilege('anon', x.nome, 'INSERT')), false)::text
          from (values ('public.claim_eventos'), ('public.claim_sets'), ('public.claim_reservas'), ('public.claim_reservas_quadro')) x(nome))
union all select 'colunas pessoais no quadro dos sets (esperado 0)', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'claim_reservas_quadro' and column_name ~* '(email|cpf|whatsapp)')::text
union all select 'funções de claim seguras (esperado 3)', (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('claim_enviar', 'claim_organizar', '_claim_organizar_interno') and p.prosecdef and p.proconfig = array['search_path=""'])::text
union all select 'visitante executa claim_enviar/claim_organizar (esperado false)', (has_function_privilege('anon', 'public.claim_enviar(bigint,jsonb)', 'EXECUTE') or has_function_privilege('anon', 'public.claim_organizar(bigint)', 'EXECUTE'))::text
union all select 'impressão antes | agora (claim_reservas)', coalesce((select detalhe from emergencia.c0b_estado_anterior where etapa = 'J4c-4b' and objeto = 'impressão claim_reservas'), 'sem registro') || ' | ' || (select 'linhas=' || count(*) || ' md5=' || md5(coalesce(string_agg(id::text || coalesce(status, ''), ',' order by id::text), '')) from public.claim_reservas)
union all select 'estado registrado (linhas J4c-4b, esperado >= 9)', (select count(*) from emergencia.c0b_estado_anterior where etapa = 'J4c-4b')::text;
